11	import com.loja.checkout.entrega.OpcaoEntrega;
12	import com.loja.checkout.erro.CodigoErro;
13	import com.loja.checkout.erro.PedidoInvalidoException;
14	import com.loja.checkout.pagamento.CatalogoPagamentos;
