18	import java.math.BigDecimal;
19	import java.util.List;
20	import org.springframework.stereotype.Service;
21	
22	@Service
23	public class ResumoCompraService {
24	
25	    private final CatalogoEntregas catalogoEntregas;
26	    private final CatalogoCupons catalogoCupons;
27	    private final CatalogoClube catalogoClube;
28	    private final CatalogoPagamentos catalogoPagamentos;
29	    private final CatalogoRegioes catalogoRegioes;
30	
31	    public ResumoCompraService(
32	            CatalogoEntregas catalogoEntregas,
33	            CatalogoCupons catalogoCupons,
34	            CatalogoClube catalogoClube,
35	            CatalogoPagamentos catalogoPagamentos,
36	            CatalogoRegioes catalogoRegioes) {
37	        this.catalogoEntregas = catalogoEntregas;
38	        this.catalogoCupons = catalogoCupons;
39	        this.catalogoClube = catalogoClube;
40	        this.catalogoPagamentos = catalogoPagamentos;
41	        this.catalogoRegioes = catalogoRegioes;
42	    }
43	
44	    public ResumoResponse calcular(ResumoRequest pedido) {
45	        validarItens(pedido.itens());
46	        BeneficioClube beneficioClube = validarClube(pedido.nivelClube());
47	        BigDecimal percentualSeguro = validarRegiao(pedido.regiao());
48	        OpcaoEntrega opcaoEntrega = validarModalidadeEntrega(pedido.modalidadeEntrega());
49	
50	        BigDecimal subtotalProdutos = Dinheiro.arredondar(subtotal(pedido.itens()));
51	        BigDecimal pesoPedido = pesoTotal(pedido.itens());
52	
53	        if (!opcaoEntrega.disponivel(pesoPedido)) {
54	            throw new PedidoInvalidoException(CodigoErro.MODALIDADE_INDISPONIVEL);
55	        }
56	
57	        BigDecimal freteBase = Dinheiro.arredondar(opcaoEntrega.custo(pesoPedido));
58	        BigDecimal frete = Dinheiro.arredondar(beneficioClube.frete(freteBase));
59	
60	        Cupom cupom = validarCupom(pedido.cupom(), pedido.itens(), subtotalProdutos);
61	        BigDecimal descontoCupom = cupom == null
62	                ? BigDecimal.ZERO.setScale(2)
63	                : Dinheiro.arredondar(cupom.desconto(pedido.itens(), subtotalProdutos, frete));
64	
65	        BigDecimal seguro = Dinheiro.arredondar(subtotalProdutos.multiply(percentualSeguro));
66	
67	        BigDecimal totalPedido = subtotalProdutos.subtract(descontoCupom).add(frete).add(seguro);
68	
69	        FormaPagamento formaPagamento = validarFormaPagamento(pedido.formaPagamento());
70	        int parcelas = pedido.parcelas() == null ? 1 : pedido.parcelas();
71	        if (!formaPagamento.parcelasPermitidas(parcelas)) {
72	            throw new PedidoInvalidoException(CodigoErro.PARCELAMENTO_INVALIDO);
73	        }
74	        if (!formaPagamento.disponivel(totalPedido)) {
75	            throw new PedidoInvalidoException(CodigoErro.FORMA_PAGAMENTO_INDISPONIVEL);
76	        }
77	
78	        ResultadoPagamento resultadoPagamento = formaPagamento.calcular(totalPedido, parcelas);
79	
80	        BigDecimal creditoProximaCompra = Dinheiro.arredondar(beneficioClube.credito(subtotalProdutos));
81	        boolean brinde = beneficioClube.brinde(subtotalProdutos);
82	
83	        return new ResumoResponse(
84	                subtotalProdutos,
85	                descontoCupom,
86	                frete,
87	                opcaoEntrega.prazoDias(),
88	                seguro,
89	                resultadoPagamento.ajuste(),
90	                resultadoPagamento.totalFinal(),
91	                parcelas,
92	                resultadoPagamento.valorParcela(),
93	                creditoProximaCompra,
94	                brinde
95	        );
96	    }
97	
98	    private void validarItens(List<ItemRequest> itens) {
99	        if (itens == null || itens.isEmpty()) {
100	            throw new PedidoInvalidoException(CodigoErro.PEDIDO_INVALIDO);
101	        }
102	        for (ItemRequest item : itens) {
103	            if (item.precoUnitario() == null || item.precoUnitario().signum() <= 0
104	                    || item.quantidade() == null || item.quantidade() <= 0
105	                    || item.pesoKg() == null || item.pesoKg().signum() <= 0) {
106	                throw new PedidoInvalidoException(CodigoErro.PEDIDO_INVALIDO);
107	            }
108	        }
109	    }
110	
111	    private BeneficioClube validarClube(String nivelClube) {
112	        BeneficioClube beneficioClube = nivelClube == null ? null : catalogoClube.buscar(nivelClube);
113	        if (beneficioClube == null) {
114	            throw new PedidoInvalidoException(CodigoErro.NIVEL_CLUBE_INVALIDO);
115	        }
116	        return beneficioClube;
117	    }
118	
119	    private BigDecimal validarRegiao(String regiao) {
120	        BigDecimal percentual = regiao == null ? null : catalogoRegioes.percentualSeguro(regiao);
121	        if (percentual == null) {
122	            throw new PedidoInvalidoException(CodigoErro.REGIAO_INVALIDA);
123	        }
124	        return percentual;
125	    }
126	
127	    private OpcaoEntrega validarModalidadeEntrega(String modalidadeEntrega) {
128	        OpcaoEntrega opcaoEntrega = modalidadeEntrega == null ? null : catalogoEntregas.buscar(modalidadeEntrega);
129	        if (opcaoEntrega == null) {
130	            throw new PedidoInvalidoException(CodigoErro.MODALIDADE_INVALIDA);
131	        }
132	        return opcaoEntrega;
133	    }
134	
135	    private Cupom validarCupom(String codigoCupom, List<ItemRequest> itens, BigDecimal subtotalProdutos) {
136	        if (codigoCupom == null) {
137	            return null;
138	        }
139	        Cupom cupom = catalogoCupons.buscar(codigoCupom);
140	        if (cupom == null) {
141	            throw new PedidoInvalidoException(CodigoErro.CUPOM_INVALIDO);
142	        }
143	        if (!cupom.aplicavel(itens, subtotalProdutos)) {
144	            throw new PedidoInvalidoException(CodigoErro.CUPOM_NAO_APLICAVEL);
145	        }
146	        return cupom;
147	    }
148	
149	    private FormaPagamento validarFormaPagamento(String formaPagamento) {
150	        FormaPagamento forma = formaPagamento == null ? null : catalogoPagamentos.buscar(formaPagamento);
151	        if (forma == null) {
152	            throw new PedidoInvalidoException(CodigoErro.FORMA_PAGAMENTO_INVALIDA);
153	        }
154	        return forma;
155	    }
156	
157	    private BigDecimal subtotal(List<ItemRequest> itens) {
158	        BigDecimal subtotal = BigDecimal.ZERO;
159	        for (ItemRequest item : itens) {
160	            subtotal = subtotal.add(item.precoUnitario().multiply(BigDecimal.valueOf(item.quantidade())));
161	        }
162	        return subtotal;
163	    }
164	
165	    private BigDecimal pesoTotal(List<ItemRequest> itens) {
166	        BigDecimal peso = BigDecimal.ZERO;
167	        for (ItemRequest item : itens) {
168	            peso = peso.add(item.pesoKg().multiply(BigDecimal.valueOf(item.quantidade())));
169	        }
170	        return peso;
171	    }
172	}
