1	package com.loja.checkout.pagamento;
2	
3	import com.loja.checkout.Dinheiro;
4	import java.math.BigDecimal;
5	import java.math.MathContext;
6	
7	public class Cartao implements FormaPagamento {
8	
9	    private static final int PARCELAS_SEM_JUROS = 3;
10	    private static final BigDecimal TAXA_JUROS_MENSAL = new BigDecimal("0.0199");
11	    private static final MathContext PRECISAO = new MathContext(30);
12	
13	    @Override
14	    public boolean parcelasPermitidas(int parcelas) {
15	        return parcelas >= 1 && parcelas <= 12;
16	    }
17	
18	    @Override
19	    public boolean disponivel(BigDecimal totalPedido) {
20	        return true;
21	    }
22	
23	    @Override
24	    public ResultadoPagamento calcular(BigDecimal totalPedido, int parcelas) {
25	        if (parcelas <= PARCELAS_SEM_JUROS) {
26	            BigDecimal valorParcela = Dinheiro.arredondar(
27	                    totalPedido.divide(BigDecimal.valueOf(parcelas), PRECISAO));
28	            return new ResultadoPagamento(Dinheiro.arredondar(BigDecimal.ZERO), totalPedido, valorParcela);
29	        }
30	
31	        BigDecimal baseComposta = BigDecimal.ONE.add(TAXA_JUROS_MENSAL).pow(parcelas);
32	        BigDecimal denominador = BigDecimal.ONE.subtract(BigDecimal.ONE.divide(baseComposta, PRECISAO));
33	        BigDecimal valorParcela = Dinheiro.arredondar(
34	                totalPedido.multiply(TAXA_JUROS_MENSAL).divide(denominador, PRECISAO));
35	        BigDecimal totalFinal = valorParcela.multiply(BigDecimal.valueOf(parcelas));
36	        BigDecimal ajuste = totalFinal.subtract(totalPedido);
37	        return new ResultadoPagamento(ajuste, totalFinal, valorParcela);
38	    }
39	}
